window.TIMING = {"open-title":{"dur":42.95,"beats":[{"start":2.2,"sents":[{"start":2.2,"end":5.69,"cap":"A student working through methods for SNP data kept getting stuck on one question."},{"start":6.09,"end":9.68,"cap":"To estimate relatedness, you seem to need to know how inbred the population is."},{"start":10.08,"end":13.2,"cap":"To estimate inbreeding, you seem to need to know how related its members are."}],"end":13.2},{"start":13.95,"sents":[{"start":13.95,"end":15.37,"cap":"It looks like a chicken-and-egg problem."},{"start":15.77,"end":19.04,"cap":"In this program we take it apart, and show that most of the circle is an illusion."}],"end":19.04},{"start":19.79,"sents":[{"start":19.79,"end":22.56,"cap":"Relatedness and inbreeding are one quantity, seen from two angles."},{"start":22.96,"end":27.57,"cap":"The genuine dependency lies elsewhere, in the reference population: its allele frequencies and its structure."},{"start":27.97,"end":29.4,"cap":"And there are good tools for handling it."}],"end":29.4},{"start":30.75,"sents":[{"start":30.75,"end":34.27,"cap":"We build from first principles to the methods you will actually run, and when each one works."},{"start":34.67,"end":36.43,"cap":"Watch the lexicon on the right of the screen."},{"start":36.83,"end":39.45,"cap":"Every numbered term is collected in the companion study guide."}],"end":39.45}],"sig":"787:0,0,0.6,1.5"},"ibd-card":{"dur":8.3,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.66,"cap":"Chapter one."},{"start":2.06,"end":6.7,"cap":"Identity by descent: the single idea beneath both relatedness and inbreeding."}],"end":6.7}],"sig":"90:0"},"ibd-ibs":{"dur":42.03,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.26,"cap":"Two alleles are identical by state when they carry the same sequence."},{"start":4.66,"end":9.6,"cap":"They are identical by descent when both are copies of one ancestral allele, inherited through the pedigree."}],"end":9.6},{"start":10.35,"sents":[{"start":10.35,"end":11.89,"cap":"Follow one allele in a grandparent."},{"start":12.29,"end":17.23,"cap":"Through Mendelian segregation, a copy passes to each of two children, and from them to two cousins."},{"start":17.63,"end":20.19,"cap":"The cousins now carry alleles that are identical by descent."}],"end":20.19},{"start":20.94,"sents":[{"start":20.94,"end":26.02,"cap":"Identity by state is what we observe, and at a marker with two alleles it happens by chance all the time."},{"start":26.42,"end":29.82,"cap":"Two strangers can carry the same letter for entirely different ancestral reasons."}],"end":29.82},{"start":30.57,"sents":[{"start":30.57,"end":33.1,"cap":"Every method in this program does the same basic job."},{"start":33.5,"end":40.13,"cap":"It infers identity by descent from observed identity by state, after subtracting the chance matching expected from allele frequencies."}],"end":40.13}],"sig":"751:0,0,0,0.6"},"ibd-kinship":{"dur":42.06,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":9.56,"cap":"The kinship coefficient, φ, is the probability that an allele drawn at random from individual i, and one drawn at the same locus from individual j, are identical by descent."}],"end":9.56},{"start":10.31,"sents":[{"start":10.31,"end":11.67,"cap":"Take a parent and its offspring."},{"start":12.07,"end":14.97,"cap":"Half the time, the allele drawn from the child is the one this parent gave it."},{"start":15.37,"end":18.42,"cap":"Half the time after that, the draw from the parent picks that same allele."},{"start":18.82,"end":20.08,"cap":"So φ = ¼."}],"end":20.08},{"start":20.83,"sents":[{"start":20.83,"end":23.63,"cap":"Full siblings share both parents, and their kinship is also one quarter."},{"start":24.03,"end":26.13,"cap":"Half siblings share one parent, with kinship one eighth."},{"start":26.53,"end":28.3,"cap":"First cousins have kinship one sixteenth."}],"end":28.3},{"start":29.05,"sents":[{"start":29.05,"end":40.76,"cap":"In general, kinship sums over every path through a common ancestor A. A path through n individuals, counting i and j, contributes (½)ⁿ (1 + F_A), where F_A is the inbreeding of the ancestor itself."}],"end":40.76}],"sig":"788:0,0,0,0"},"ibd-inbreeding":{"dur":52.24,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":7.11,"cap":"The inbreeding coefficient, F, is the probability that the two alleles within a single individual are identical by descent."}],"end":7.11},{"start":7.86,"sents":[{"start":7.86,"end":9.26,"cap":"Where did those two alleles come from?"},{"start":9.66,"end":11.37,"cap":"One from the mother, and one from the father."},{"start":11.77,"end":14.88,"cap":"So an individual's F is exactly the kinship of its parents."},{"start":15.28,"end":17.8,"cap":"Inbreeding is relatedness, one generation back."}],"end":17.8},{"start":18.55,"sents":[{"start":18.55,"end":21.59,"cap":"Here, two half siblings mate, closing a loop in the pedigree."},{"start":21.99,"end":25.99,"cap":"Their kinship is one eighth, so their offspring is inbred, with F equal to one eighth."}],"end":25.99},{"start":26.74,"sents":[{"start":26.74,"end":29.2,"cap":"Now draw twice from one individual, with replacement."},{"start":29.6,"end":31.34,"cap":"Half the time you pick the same allele twice."},{"start":31.74,"end":38.31,"cap":"Otherwise you pick both, and they match by descent with probability F. That gives the self-kinship, (1 + F) / 2."}],"end":38.31},{"start":39.06,"sents":[{"start":39.06,"end":40.83,"cap":"So arrange every kinship in one matrix."},{"start":41.23,"end":44.92,"cap":"Pairwise kinship fills the off-diagonal, and inbreeding sits on the diagonal."},{"start":45.32,"end":48,"cap":"Both come from the same genotypes, estimated together."},{"start":48.4,"end":50.14,"cap":"You never need one in order to get the other."}],"end":50.14}],"sig":"906:0,0,0,0,0.8"},"ibd-r":{"dur":43.72,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.36,"cap":"Relatedness, r, is the scale most ecologists report."},{"start":4.76,"end":12.98,"cap":"For outbred individuals it is simply twice the kinship: one half for parent and offspring and for full siblings, one quarter for half siblings, one eighth for first cousins."}],"end":12.98},{"start":13.73,"sents":[{"start":13.73,"end":16.39,"cap":"Those tidy values hold only when nobody is inbred."},{"start":16.79,"end":23.61,"cap":"Wright's definition allows for inbreeding: r equals 2φ, divided by the square root of (1 + F_i)(1 + F_j)."}],"end":23.61},{"start":24.36,"sents":[{"start":24.36,"end":28.81,"cap":"If the parents of a sibship are themselves related, the siblings share more than the textbook half."},{"start":29.21,"end":33.04,"cap":"A correct estimator should report relatedness above one half, and that is not a bias."}],"end":33.04},{"start":33.79,"sents":[{"start":33.79,"end":37.87,"cap":"Much of the confusion behind our puzzle comes from treating one half and one quarter as fixed facts."},{"start":38.27,"end":41.62,"cap":"They are expectations for one special case: an outbred pedigree."}],"end":41.62}],"sig":"754:0,0,0,0.8"},"base-card":{"dur":7.29,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.58,"cap":"Chapter two."},{"start":1.98,"end":5.69,"cap":"The reference population: identity by descent, relative to what?"}],"end":5.69}],"sig":"77:0"},"base-relative":{"dur":48.16,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.34,"cap":"Go back far enough and every pair of individuals shares an ancestor."},{"start":4.74,"end":8.98,"cap":"Given enough generations, every allele in a population is identical by descent with every other."},{"start":9.38,"end":15.44,"cap":"So identity by descent only has meaning relative to a base population: a point in the past where we declare everyone unrelated."}],"end":15.44},{"start":16.19,"sents":[{"start":16.19,"end":19.16,"cap":"Pedigree coefficients set that base at the founders of the pedigree."},{"start":19.56,"end":25.72,"cap":"Marker-based estimators set it implicitly, through the allele frequencies you supply, which are usually estimated from your own sample."}],"end":25.72},{"start":26.47,"sents":[{"start":26.47,"end":28.1,"cap":"That makes marker estimates relative."},{"start":28.5,"end":32.55,"cap":"They ask whether a pair is more related than the average pair in your sample, which is set to zero."},{"start":32.95,"end":36.34,"cap":"Pairs less related than average receive negative values, and that is not an error."}],"end":36.34},{"start":37.09,"sents":[{"start":37.09,"end":38.68,"cap":"This is where the real dependency lives."},{"start":39.08,"end":43.35,"cap":"Not between relatedness and inbreeding, but between both of them and the reference allele frequencies."},{"start":43.75,"end":46.06,"cap":"Change the reference, and every estimate shifts together."}],"end":46.06}],"sig":"921:0,0,0,0.8"},"base-estimators":{"dur":47.7,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.42,"cap":"How do estimators turn identity by state into identity by descent?"},{"start":4.82,"end":8.72,"cap":"Sharing a common allele is weak evidence, because almost any two individuals would share it."},{"start":9.12,"end":11.03,"cap":"Sharing a rare allele is strong evidence."}],"end":11.03},{"start":11.78,"sents":[{"start":11.78,"end":14.59,"cap":"Moment estimators weight every locus by its allele frequency."},{"start":14.99,"end":24.47,"cap":"The genomic relationship matrix is the clearest example: center each genotype by twice the allele frequency, scale by its expected variance, and average the cross-products across loci."}],"end":24.47},{"start":25.22,"sents":[{"start":25.22,"end":29.77,"cap":"The Queller and Goodnight, Lynch and Ritland, and Wang estimators follow the same logic with different weights."},{"start":30.17,"end":35.91,"cap":"They differ in bias and variance, especially when loci are few or individuals are inbred, so compare them on your own data."}],"end":35.91},{"start":36.66,"sents":[{"start":36.66,"end":38.62,"cap":"Their shared weak point is the allele frequency."},{"start":39.02,"end":44.8,"cap":"If it is wrong, perhaps estimated from a small sample or from a mixture of populations, every estimate inherits the error."},{"start":45.2,"end":46.4,"cap":"Which brings us to structure."}],"end":46.4}],"sig":"886:0,0,0,0"},"base-structure":{"dur":63.08,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":6.6,"cap":"Suppose your sample spans two genetically differentiated populations, and you estimate allele frequencies from the pooled sample."},{"start":7,"end":10.21,"cap":"An allele that is common in one population looks much less common overall."}],"end":10.21},{"start":10.96,"sents":[{"start":10.96,"end":16.49,"cap":"Now two unrelated individuals from the same population share that allele, and the estimator reads the match as kinship."},{"start":16.89,"end":21.1,"cap":"Pairs within a population look related, and pairs between populations look negatively related."}],"end":21.1},{"start":21.85,"sents":[{"start":21.85,"end":27.1,"cap":"The same mixture also produces a deficit of heterozygotes, the Wahlund effect, which mimics inbreeding."},{"start":27.5,"end":29.46,"cap":"Structure inflates both quantities at once."},{"start":29.86,"end":31.18,"cap":"That is the true chicken and egg."}],"end":31.18},{"start":31.93,"sents":[{"start":31.93,"end":32.84,"cap":"There are two remedies."},{"start":33.24,"end":39.18,"cap":"Analyze each genetic cluster separately, after identifying clusters with PCA, ADMIXTURE, or the sNMF method."},{"start":39.58,"end":41.72,"cap":"Or use estimators that are robust to structure."},{"start":42.12,"end":45.32,"cap":"KING-robust compares a pair without using sample allele frequencies at all."}],"end":45.32},{"start":46.07,"sents":[{"start":46.07,"end":48.71,"cap":"PC-AiR and PC-Relate resolve the loop explicitly."},{"start":49.11,"end":50.97,"cap":"KING finds a set of unrelated individuals."},{"start":51.37,"end":53.71,"cap":"Principal components from that set define ancestry."},{"start":54.11,"end":59.18,"cap":"PC-Relate then estimates kinship and inbreeding using allele frequencies specific to each individual's ancestry."},{"start":59.58,"end":60.98,"cap":"The circle becomes an iteration."}],"end":60.98}],"sig":"1157:0,0,0,0,0.8"},"rel-card":{"dur":7.89,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.7,"cap":"Chapter three."},{"start":2.1,"end":6.29,"cap":"Reading relationships: what a pair's genotypes can tell you, and what they cannot."}],"end":6.29}],"sig":"97:0"},"rel-cotterman":{"dur":57.67,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":5.35,"cap":"At any locus, an outbred pair shares zero, one, or two alleles identical by descent."},{"start":5.75,"end":10.97,"cap":"Cotterman's coefficients, k0, k1 and k2, give the probability of each, and they sum to one."}],"end":10.97},{"start":11.72,"sents":[{"start":11.72,"end":15.15,"cap":"Parent and offspring always share exactly one: k1 equals one."},{"start":15.55,"end":20,"cap":"Full siblings share zero, one or two, with probabilities one quarter, one half, and one quarter."},{"start":20.4,"end":24.46,"cap":"Both relationships have kinship one quarter, but they sit at different points in this space."}],"end":24.46},{"start":25.21,"sents":[{"start":25.21,"end":29.85,"cap":"Kinship is a line through the space: φ = k1/4 + k2/2."},{"start":30.25,"end":34.69,"cap":"Relationship-inference methods use the position along that line, not just which line a pair is on."}],"end":34.69},{"start":35.44,"sents":[{"start":35.44,"end":41.21,"cap":"Half siblings, an aunt and her nephew, and a grandparent and grandchild all have k0 and k1 equal to one half."},{"start":41.61,"end":42.76,"cap":"They occupy the same point."},{"start":43.16,"end":48.89,"cap":"No method using unlinked markers can separate them; that takes linkage information, or ancillary data such as ages."}],"end":48.89},{"start":49.64,"sents":[{"start":49.64,"end":52.48,"cap":"Unrelated pairs sit in the corner, where k0 equals one."},{"start":52.88,"end":56.37,"cap":"Real estimates scatter around each point, because every locus is a noisy draw."}],"end":56.37}],"sig":"1026:0,0,0,0,0"},"rel-jacquard":{"dur":63.55,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.75,"cap":"Cotterman's space assumes that neither individual is inbred."},{"start":4.15,"end":8.2,"cap":"Allow inbreeding, and each individual's own two alleles may also be identical by descent."}],"end":8.2},{"start":8.95,"sents":[{"start":8.95,"end":18.87,"cap":"Among four alleles, two in each individual, there are fifteen patterns of identity, which collapse to nine distinguishable states: Jacquard's condensed identity coefficients, Δ1 to Δ9."},{"start":19.27,"end":24.47,"cap":"For an outbred pair, only the last three remain, and they are Cotterman's k2, k1 and k0."}],"end":24.47},{"start":25.22,"sents":[{"start":25.22,"end":32.87,"cap":"Kinship is still perfectly well defined: φ = Δ1 + ½(Δ3 + Δ5 + Δ7) + ¼Δ8."},{"start":33.27,"end":36.57,"cap":"What breaks is the mapping from estimated coefficients to named relationships."}],"end":36.57},{"start":37.32,"sents":[{"start":37.32,"end":40.68,"cap":"Force an inbred pair into the three-coefficient model and it lands in the wrong place."},{"start":41.08,"end":47.81,"cap":"Inbred half siblings can share two alleles by descent, drifting toward full siblings, and an inbred parent and offspring slide off their corner."},{"start":48.21,"end":52.28,"cap":"Misclassification is the main danger, and three-coefficient kinship can be biased too."}],"end":52.28},{"start":53.03,"sents":[{"start":53.03,"end":55.39,"cap":"Pairwise estimators can be built on all nine states."},{"start":55.79,"end":62.25,"cap":"NgsRelate version two estimates them from genotype likelihoods, and the related package allows inbreeding in its likelihood estimators."}],"end":62.25}],"sig":"1198:0,0,0,0,0"},"rel-segments":{"dur":57.46,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.75,"cap":"Linked markers carry more information than their count suggests."},{"start":4.15,"end":11.89,"cap":"Identity by descent arrives in segments: stretches of chromosome inherited intact from a shared ancestor, and cut shorter by recombination every generation."}],"end":11.89},{"start":12.64,"sents":[{"start":12.64,"end":16.14,"cap":"A grandparent and grandchild share long segments, cut by a single meiosis."},{"start":16.54,"end":20.65,"cap":"Half siblings' segments pass through two meioses, an aunt and nephew's through three."},{"start":21.05,"end":27.09,"cap":"The same expected sharing arrives in different lengths and numbers of pieces, and that is how linkage-aware methods tell these relationships apart."}],"end":27.09},{"start":27.84,"sents":[{"start":27.84,"end":29.93,"cap":"Segments also reveal realized relatedness."},{"start":30.33,"end":42.9,"cap":"Full siblings are expected to share one half, but Mendelian sampling is random, so the actual fraction varies, roughly from 0.4 to 0.6 in humans, and more widely in species with shorter genetic maps, meaning fewer chromosomes or crossovers."},{"start":43.3,"end":45.55,"cap":"Genomic estimates measure what was actually inherited."}],"end":45.55},{"start":46.3,"sents":[{"start":46.3,"end":51.19,"cap":"Using segments requires a reference genome, ideally assembled to chromosomes, and dense markers along it."},{"start":51.59,"end":55.56,"cap":"A panel of a few hundred amplicons cannot see segments; whole-genome data can."}],"end":55.56}],"sig":"1077:0,0,0,0.6"},"rel-sexbias":{"dur":58.28,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.66,"cap":"Many ecological questions never need a named relationship."},{"start":4.06,"end":11.76,"cap":"Take sex-biased dispersal: if females stay near where they were born and males disperse, nearby females should be more related to one another than nearby males."}],"end":11.76},{"start":12.51,"sents":[{"start":12.51,"end":19.5,"cap":"Estimate kinship for every female–female, female–male, and male–male pair, and compare the classes, often as a function of the distance between them."}],"end":19.5},{"start":20.25,"sents":[{"start":20.25,"end":28.74,"cap":"Any bias that shifts the baseline, from inbreeding or from imperfect allele frequencies, shifts all the classes roughly together, as long as the sexes share one ancestry mix."},{"start":29.14,"end":32.82,"cap":"The question concerns the difference between classes, and the shared offset cancels."}],"end":32.82},{"start":33.57,"sents":[{"start":33.57,"end":35.1,"cap":"Test the difference by permutation."},{"start":35.5,"end":39.92,"cap":"Shuffle the sex labels, recompute, and ask how often a difference this large arises by chance."},{"start":40.32,"end":45.49,"cap":"Spatial autocorrelation by pair class, in the style of Smouse and Peakall, does the same along a distance axis."}],"end":45.49},{"start":46.24,"sents":[{"start":46.24,"end":48.33,"cap":"Nor do you need to account separately for shared parents."},{"start":48.73,"end":53.68,"cap":"Kinship is already the sum of all shared ancestry, through every path, including shared parents and inbreeding loops."},{"start":54.08,"end":56.18,"cap":"It is exactly the quantity this question needs."}],"end":56.18}],"sig":"1096:0,0,0,0,0.8"},"inb-card":{"dur":8.43,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.68,"cap":"Chapter four."},{"start":2.08,"end":6.83,"cap":"Measuring inbreeding: what heterozygosity hides, and what runs of homozygosity reveal."}],"end":6.83}],"sig":"100:0"},"inb-fis":{"dur":57.99,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":10.73,"cap":"The classic summary compares observed heterozygosity with the heterozygosity expected under Hardy–Weinberg proportions: F_IS = 1 − H_O / H_E."}],"end":10.73},{"start":11.48,"sents":[{"start":11.48,"end":18.76,"cap":"F_IS measures non-random mating relative to the current population: whether mates are more related than two random members of this generation."},{"start":19.16,"end":20.68,"cap":"That is not the same as being inbred."}],"end":20.68},{"start":21.43,"sents":[{"start":21.43,"end":24.34,"cap":"Watch a small, closed population that mates completely at random."},{"start":24.74,"end":34.25,"cap":"Drift makes everyone slightly more related each generation, and inbreeding accumulates: F_t = 1 − (1 − 1/2N)^t."}],"end":34.25},{"start":35,"sents":[{"start":35,"end":43.2,"cap":"But because everyone is equally related, mates are no more related than random pairs, and observed heterozygosity keeps tracking its expectation, even as both decline."},{"start":43.6,"end":46.45,"cap":"F_IS stays near zero while true inbreeding climbs."}],"end":46.45},{"start":47.2,"sents":[{"start":47.2,"end":50.71,"cap":"A bottlenecked population can be deeply inbred with an F_IS of zero."},{"start":51.11,"end":55.89,"cap":"Heterozygosity compared with today's expectation cannot see inbreeding that the whole population shares."}],"end":55.89}],"sig":"959:0,0,0,0,0.8"},"inb-artifacts":{"dur":49.76,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.31,"cap":"A heterozygote deficit can also be manufactured."},{"start":3.71,"end":9.1,"cap":"The first culprit is structure: pool two populations, and the Wahlund effect removes heterozygotes that were never missing."}],"end":9.1},{"start":9.85,"sents":[{"start":9.85,"end":11.03,"cap":"The second is genotyping."},{"start":11.43,"end":16.06,"cap":"At low sequencing depth, one allele of a heterozygote may never be read, and the call becomes a homozygote."},{"start":16.46,"end":20.53,"cap":"Allelic dropout and null alleles do the same, and with RADseq data they can dominate the signal."}],"end":20.53},{"start":21.28,"sents":[{"start":21.28,"end":25.49,"cap":"A useful diagnostic: plot each individual's heterozygosity against its mean depth."},{"start":25.89,"end":29.07,"cap":"If heterozygosity rises with depth, the apparent inbreeding is technical."},{"start":29.47,"end":33.47,"cap":"Apply depth filters, or use methods that work with genotype likelihoods rather than hard calls."}],"end":33.47},{"start":34.22,"sents":[{"start":34.22,"end":35.48,"cap":"The third culprit is filtering."},{"start":35.88,"end":43.43,"cap":"Removing loci that depart from Hardy–Weinberg proportions preferentially discards those with the largest heterozygote deficits, biasing inbreeding estimates downward."},{"start":43.83,"end":45.72,"cap":"Filter within populations, and leniently."},{"start":46.12,"end":48.46,"cap":"Minor allele frequency filters shift the estimates too."}],"end":48.46}],"sig":"954:0,0,0,0"},"inb-g2":{"dur":54.62,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":8.48,"cap":"Individual estimates of F come in several flavors: F_hom from PLINK, and F_GRM and F_UNI from the GCTA software."},{"start":8.88,"end":13.68,"cap":"All are still relative to the sample's allele frequencies, and all are noisy when markers are few."}],"end":13.68},{"start":14.43,"sents":[{"start":14.43,"end":19.27,"cap":"Before trusting them, ask a prior question: does inbreeding vary among individuals at all?"},{"start":19.67,"end":27.45,"cap":"If it does, an inbred individual tends to be homozygous across its whole genome, so heterozygosity at one set of loci predicts heterozygosity at another."}],"end":27.45},{"start":28.2,"sents":[{"start":28.2,"end":35.27,"cap":"That correlation is called identity disequilibrium, and g2 measures it as the excess covariance in heterozygosity between pairs of loci."},{"start":35.67,"end":40.61,"cap":"A simpler view splits the loci into random halves and correlates each individual's heterozygosity across them."}],"end":40.61},{"start":41.36,"sents":[{"start":41.36,"end":49.47,"cap":"If g2 is indistinguishable from zero, differences in individual F are mostly sampling noise, and heterozygosity–fitness correlations built on them will be weak."},{"start":49.87,"end":52.72,"cap":"The inbreedR package estimates g2 with confidence intervals."}],"end":52.72}],"sig":"941:0,0,0,0.6"},"inb-roh":{"dur":57.18,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":7.35,"cap":"When an individual's parents share an ancestor, the individual can inherit the same chromosome segment twice, once through each parent."},{"start":7.75,"end":12.45,"cap":"The result is a long run of homozygosity: the physical footprint of autozygosity."}],"end":12.45},{"start":13.2,"sents":[{"start":13.2,"end":15.8,"cap":"The fraction of the genome inside such runs is F_ROH."},{"start":16.2,"end":24.67,"cap":"It depends far less on allele frequencies or a reference sample, so it largely sidesteps the base-population problem, and it captures the drift inbreeding that F_IS misses."}],"end":24.67},{"start":25.42,"sents":[{"start":25.42,"end":33.78,"cap":"A half-sibling mating leaves, on average, one eighth of the genome in runs, and those runs are long, because only a few meioses separate the common ancestor from the individual."}],"end":33.78},{"start":34.53,"sents":[{"start":34.53,"end":36.11,"cap":"Runs also carry a time stamp."},{"start":36.51,"end":42.27,"cap":"A common ancestor g generations back leaves runs with an expected length of about 100 / 2g centimorgans."},{"start":42.67,"end":47.07,"cap":"Recent inbreeding makes long runs; old background relatedness leaves many short ones."}],"end":47.07},{"start":47.82,"sents":[{"start":47.82,"end":55.28,"cap":"In wild populations, F_ROH has tracked realized inbreeding better than pedigree F, because it measures what was actually inherited, not what the pedigree expects."}],"end":55.28}],"sig":"1021:0,0,0,0,0.6"},"inb-roh-calls":{"dur":73.96,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.49,"cap":"This is where the warnings in the literature on runs of homozygosity apply."},{"start":4.89,"end":7.95,"cap":"They do not say that you must know relatedness before you look for runs."},{"start":8.35,"end":10.61,"cap":"Runs are how you infer how related the parents were."}],"end":10.61},{"start":11.36,"sents":[{"start":11.36,"end":12.97,"cap":"The first warning is about history."},{"start":13.37,"end":19.67,"cap":"In a population that has long been small, short runs from old shared ancestry are abundant, even without recent consanguinity."},{"start":20.07,"end":23.71,"cap":"Partition F_ROH into length classes instead of reporting a single total."}],"end":23.71},{"start":24.46,"sents":[{"start":24.46,"end":25.68,"cap":"The second is about calling."},{"start":26.08,"end":28.79,"cap":"PLINK's defaults were designed for dense human SNP arrays."},{"start":29.19,"end":36.1,"cap":"With sparse or uneven markers such as RADseq, genotyping errors fragment real runs, and poorly covered regions become false runs."}],"end":36.1},{"start":36.85,"sents":[{"start":36.85,"end":38.28,"cap":"So choose the caller for the data."},{"start":38.68,"end":43.69,"cap":"The bcftools roh command uses a hidden Markov model with genotype likelihoods and allele frequencies."},{"start":44.09,"end":47.2,"cap":"RZooRoH partitions autozygosity into age classes."},{"start":47.6,"end":52.29,"cap":"For low coverage, ngsF-HMM and ROHan work from genotype likelihoods."},{"start":52.69,"end":56.51,"cap":"PLINK is fast, once its window and density settings match your marker spacing."}],"end":56.51},{"start":57.26,"sents":[{"start":57.26,"end":62.44,"cap":"Runs need a reference genome, ideally assembled to chromosomes, and dense, evenly spaced markers."},{"start":62.84,"end":67.16,"cap":"High-coverage whole genomes are ideal, and low coverage works with likelihood-based callers."},{"start":67.56,"end":68.66,"cap":"RADseq is marginal."},{"start":69.06,"end":72.06,"cap":"An amplicon panel of a few hundred SNPs cannot detect runs at all."}],"end":72.06}],"sig":"1282:0,0,0,0,0.6"},"meth-card":{"dur":6.87,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.62,"cap":"Chapter five."},{"start":2.02,"end":5.27,"cap":"Choosing methods: matching the tool to your data and your question."}],"end":5.27}],"sig":"81:0"},"meth-pedigree":{"dur":48.92,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.99,"cap":"Likelihood-based pedigree reconstruction turns the problem around."},{"start":4.39,"end":11.1,"cap":"Instead of estimating kinship and then guessing relationships, it proposes a whole pedigree and asks how probable the genotypes are under it."}],"end":11.1},{"start":11.85,"sents":[{"start":11.85,"end":13.44,"cap":"Inbreeding is not a nuisance here."},{"start":13.84,"end":20.48,"cap":"It is simply a loop in the pedigree, and the likelihood accounts for it automatically, because the pedigree itself generates the pattern of identity by descent."}],"end":20.48},{"start":21.23,"sents":[{"start":21.23,"end":26.48,"cap":"COLONY reconstructs sibships and parentage by maximum likelihood, with an explicit option for inbreeding."},{"start":26.88,"end":34.63,"cap":"The sequoia package is built for SNP panels of a few hundred loci, and uses birth years and age priors to separate relationships that genotypes alone cannot."}],"end":34.63},{"start":35.38,"sents":[{"start":35.38,"end":47.02,"cap":"For pairwise questions, choose estimators that permit inbreeding: NgsRelate version two, which works from genotype likelihoods, or the coancestry function in the related package, with allow.inbreeding set to true."}],"end":47.02}],"sig":"886:0,0,0,0.6"},"meth-map":{"dur":55.29,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.49,"cap":"Put the pieces together as a map."},{"start":2.89,"end":4.84,"cap":"Across the top is the question you are asking."},{"start":5.24,"end":6.71,"cap":"Down the side is the data you have."}],"end":6.71},{"start":7.46,"sents":[{"start":7.46,"end":12.07,"cap":"For mean kinship among classes of pairs, as in sex-biased dispersal, almost any data will do."},{"start":12.47,"end":17.75,"cap":"Moment estimators or a genomic relationship matrix, with permutation tests, work even with a few hundred SNPs."}],"end":17.75},{"start":18.5,"sents":[{"start":18.5,"end":24.63,"cap":"For parentage and sibships, likelihood pedigree methods work from a few hundred well-chosen SNPs upward, especially with age data."},{"start":25.03,"end":32.22,"cap":"Separating half siblings from grandparents or aunts needs segments from dense markers on a chromosome-level assembly, or else ages and pedigree context."}],"end":32.22},{"start":32.97,"sents":[{"start":32.97,"end":37.83,"cap":"For individual inbreeding, a sparse panel supports only noisy marker-based F, worth checking with g2."},{"start":38.23,"end":41.54,"cap":"RADseq supports likelihood-based heterozygosity and cautious runs."},{"start":41.94,"end":45.44,"cap":"Whole genomes support F_ROH by length class, the most informative measure."}],"end":45.44},{"start":46.19,"sents":[{"start":46.19,"end":48.12,"cap":"And whatever the cell, structure comes first."},{"start":48.52,"end":53.19,"cap":"If your sample spans genetic clusters, analyze within them, or use KING-robust and PC-Relate."}],"end":53.19}],"sig":"996:0,0,0,0,0.8"},"meth-simulate":{"dur":56.6,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":5.05,"cap":"The real answer to how you can ever estimate either one reliably is simulation."},{"start":5.45,"end":12.68,"cap":"Take your own allele frequencies and your own marker set, simulate pedigrees with known relationships, including inbred ones, and see what your estimators recover."}],"end":12.68},{"start":13.43,"sents":[{"start":13.43,"end":16.06,"cap":"Each relationship class produces a distribution of estimates."},{"start":16.46,"end":23.87,"cap":"With many markers, unrelated pairs, half siblings and first-degree pairs separate cleanly, and k0 then splits parent and offspring from full siblings."}],"end":23.87},{"start":24.62,"sents":[{"start":24.62,"end":27.14,"cap":"With fewer markers, or more inbreeding, they overlap."},{"start":27.54,"end":33.8,"cap":"The overlap is the misclassification rate: the fraction of half siblings that look unrelated, or full siblings that look like half siblings."}],"end":33.8},{"start":34.55,"sents":[{"start":34.55,"end":36.19,"cap":"Tools exist for exactly this."},{"start":36.59,"end":46.1,"cap":"The related package simulates families, sequoia's EstConf estimates assignment error rates, and CKMRsim computes false positive and false negative rates for each kin category."}],"end":46.1},{"start":46.85,"sents":[{"start":46.85,"end":54.7,"cap":"If the simulations show that your panel cannot separate full from half siblings at plausible levels of inbreeding, do not rely on that distinction, no matter which method you use."}],"end":54.7}],"sig":"1046:0,0,0,0,0.6"},"meth-synthesis":{"dur":50.91,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.09,"cap":"Return to the puzzle."},{"start":2.49,"end":5.88,"cap":"Relatedness seemed to need inbreeding, and inbreeding seemed to need relatedness."},{"start":6.28,"end":12.29,"cap":"But both are identity by descent, between two individuals or within one, and they are estimated together, in one matrix."}],"end":12.29},{"start":13.04,"sents":[{"start":13.04,"end":18.99,"cap":"The genuine dependency runs to the reference: the allele frequencies and population structure that define what unrelated means."},{"start":19.39,"end":22.19,"cap":"Model the structure, and the loop becomes an iteration that converges."}],"end":22.19},{"start":22.94,"sents":[{"start":22.94,"end":24,"cap":"Then follow the recipe."},{"start":24.4,"end":26.33,"cap":"Do quality control with inbreeding in mind."},{"start":26.73,"end":27.85,"cap":"Deal with structure first."},{"start":28.25,"end":29.6,"cap":"Ask whether inbreeding varies."},{"start":30,"end":31.15,"cap":"Choose methods that allow it."},{"start":31.55,"end":33.99,"cap":"Use runs of homozygosity when your data can see them."},{"start":34.39,"end":36.73,"cap":"And validate everything by simulating your own system."}],"end":36.73},{"start":37.48,"sents":[{"start":37.48,"end":42.98,"cap":"Relatedness and inbreeding are two views of one process: shared ancestry, passed down chromosome by chromosome."},{"start":43.38,"end":47.61,"cap":"Measure it against a reference you understand, and the chicken and the egg turn out to be the same bird."}],"end":47.61}],"sig":"905:0,0,0,2"}};
